        elif any(r['k']=='human' for r in rows): e=next(r for r in rows if r['k']=='human')
        elif any(r['k']=='hardship' for r in rows): e=next(r for r in rows if r['k']=='hardship')
        elif any(r['k']=='plan' for r in rows): e=next(r for r in rows if r['k']=='plan')
        else: raise ValueError('multiple decisions require clarification')
    else: e=rows[0]
    s['formats']=0
except Exception:
